/**
 * Settings that can be managed from the web UI (Settings / setup wizard). The key is the env var
 * name: a value set in the environment always wins and shows as "locked" in the UI; otherwise the
 * value saved in the database is used; otherwise the schema default.
 *
 * Bootstrap-only values (DATABASE_URL, MAS_MASTER_KEY, NODE_ENV, LOG_LEVEL, ports) are not here:
 * they are generated by the `init` container or have safe defaults.
 */
import type { ConfigKey } from './env';

export type SettingKind =
  | 'text'
  | 'host'
  | 'url'
  | 'int'
  | 'number'
  | 'bool'
  | 'secret'
  | 'pem'
  | 'timezone'
  | 'regex'
  | 'cron';

export const SETTING_SECTIONS = {
  general: {
    title: 'General',
    description: 'Time zone and the address people use to reach this dashboard.',
  },
  orion: {
    title: 'SolarWinds connection',
    description: 'The read-only Orion account MAS uses to query SWIS.',
  },
  orion_tls: {
    title: 'Orion certificate',
    description: 'How MAS verifies the Orion server’s TLS certificate.',
  },
  orion_writeback: {
    title: 'Orion write-back (optional)',
    description:
      'Acknowledge alerts in Orion when an incident is acknowledged here. Needs a separate write-capable account.',
  },
  mapping: {
    title: 'Site & division mapping',
    description: 'Which Orion node custom properties identify site, division and city.',
  },
  polling: {
    title: 'Polling',
    description: 'How often MAS reads each SWIS dataset, and how it reacts to SWIS problems.',
  },
  retention: {
    title: 'Data retention',
    description: 'How long history is kept before the nightly purge.',
  },
  correlation: {
    title: 'Correlation',
    description:
      'How raw alerts are grouped into incidents, when incidents resolve, and what counts as flapping.',
  },
  scoring: {
    title: 'Priority scoring',
    description:
      'score = Orion severity × what is affected × site tier × season × time of day. P1–P3 are thresholds on that score.',
  },
  health: {
    title: 'Self-monitoring',
    description: 'Heartbeats and the external dead-man’s switch.',
  },
} as const;
export type SettingSection = keyof typeof SETTING_SECTIONS;

export interface SettingDef {
  key: ConfigKey;
  section: SettingSection;
  label: string;
  help?: string;
  kind: SettingKind;
  placeholder?: string;
  /** Collapsed under "Advanced" in the UI. */
  advanced?: boolean;
  /** Shown with a warning style. */
  danger?: boolean;
  min?: number;
  max?: number;
}

const s = (def: SettingDef) => def;

